// A presentation layer over existing records. No migrations or deletions.
let operatorPreview='all',todaySection='next';
function staffWorkRows(){let client=scopedLeads().flatMap(l=>l.work.filter(w=>scope==='holding'||w.venture===scope).map(w=>({kind:'client',id:w.id,l,w}))),internal=db.assignments.filter(a=>scope==='holding'||db.staff.find(s=>s.id===a.owner)?.venture===scope).map(w=>({kind:'internal',id:w.id,w}));return [...client,...internal].filter(x=>operatorPreview==='all'||x.w.owner===operatorPreview||x.w.owner===db.staff.find(s=>s.id===operatorPreview)?.name)}
function staffBucket(x){return ['delivered','approved'].includes(x.w.status)?'done':/block|waiting|review|changes requested/.test(x.w.status)?'waiting':'next'}
function simpleWorkCard(x){return `<article class="simple-task"><div><span class="small">${E(x.l?.id||'internal assignment')} · ${E(x.w.venture||'team')}</span><h3>${E(x.w.title)}</h3><p>${E(workStatus(x.w))}</p><span class="small">${x.w.due?displayDate(x.w.due):'deadline to confirm'} · ${E(db.staff.find(s=>s.id===x.w.owner)?.name||x.w.owner||'owner to confirm')}</span></div>${button('open task →','task/'+x.kind+'/'+(x.l?.id||'internal')+'/'+x.id,'secondary')}</article>`}
function workFilters(){return `<div class="operator-filter"><label for="operator-filter">assignment view</label><select id="operator-filter" onchange="operatorPreview=this.value;render()"><option value="all">${scope==='holding'?'all holding work':'venture team work'}</option>${db.staff.filter(s=>scope==='holding'||s.venture===scope).map(s=>`<option value="${E(s.id)}" ${operatorPreview===s.id?'selected':''}>${E(s.name)}</option>`).join('')}</select><span class="small">role preview · live permissions are not configured</span></div>`}
const detailedTasks=taskView;
function simpleToday(){let rows=staffWorkRows(),pending=rows.filter(x=>staffBucket(x)==='next').sort((a,b)=>(Date.parse(a.w.due)||Infinity)-(Date.parse(b.w.due)||Infinity)),waiting=rows.filter(x=>staffBucket(x)==='waiting'),done=rows.filter(x=>staffBucket(x)==='done');return title('today',scope==='holding'?'what needs attention today?':'my work today.','start with the next result. open one task and follow it through.')+workFilters()+`<div class="simple-counts"><button onclick="todaySection='next';render()"><strong>${pending.length}</strong>to do</button><button onclick="todaySection='waiting';render()"><strong>${waiting.length}</strong>waiting</button><button onclick="todaySection='done';render()"><strong>${done.length}</strong>completed</button></div><section class="simple-focus"><span class="eyebrow">${todaySection==='next'?'do next':todaySection==='waiting'?'waiting on someone':'completed work'}</span>${(todaySection==='next'?pending:todaySection==='waiting'?waiting:done).slice(0,5).map(simpleWorkCard).join('')||'<h2>nothing here right now.</h2><p>your assignments will appear here when work is allocated.</p>'}</section>${button('view all my work','work','ghost')}${scope==='holding'?`<details class="simple-extra"><summary>holding results & decisions</summary>${queueView()}<div class="actions">${button('finance overview','finance','secondary')}${button('venture overview','venture','secondary')}</div></details>`:''}`}
overview=simpleToday;
taskView=function(){return title('my work','one assignment at a time.','your existing tasks, owners, standards and evidence remain together.')+workFilters()+`<div class="simple-tasklist">${staffWorkRows().map(simpleWorkCard).join('')||'<p>no assignments in this view.</p>'}</div><details class="simple-extra"><summary>assignment management & internal task creation</summary>${detailedTasks()}</details>`};
const simpleWorkspacePrevious=workspace;
workspace=function(content){let html=simpleWorkspacePrevious(content),manageActive=!['workspace','crm','lead','work','task','staff-help'].includes(route[0]);let nav=`<a class="${route[0]==='workspace'?'active':''}" href="#workspace">today</a><a class="${['crm','lead'].includes(route[0])?'active':''}" href="#crm">clients</a><a class="${['work','task'].includes(route[0])?'active':''}" href="#work">my work</a><a class="${route[0]==='staff-help'?'active':''}" href="#staff-help">help</a><details class="simple-manage" ${manageActive?'open':''}><summary>manage</summary>${growthGroups.flatMap(([name,items])=>items).filter(([p])=>!['workspace','crm','work'].includes(p)).filter(([p])=>scope==='holding'||!['finance','staff','people','content'].includes(p)).map(([p,t])=>`<a class="${route[0]===p?'active':''}" href="#${p==='venture'&&scope!=='holding'?'venture/'+encodeURIComponent(scope):p}">${t}</a>`).join('')}<a href="operations.html">calendar, standards & reports ↗</a></details><a href="#home">website ↗</a>`;return html.replace(/<nav>[\s\S]*?<\/nav>/,`<nav aria-label="staff navigation">${nav}</nav>`)};
function simpleTaskDetail(){let kind=route[1],l=lead(route[2]),w=kind==='client'?l?.work.find(w=>w.id===route[3]):db.assignments.find(w=>w.id===route[3]);if(!w||kind==='client'&&!inScope(l)||scope!=='holding'&&(kind==='client'?w.venture!==scope:db.staff.find(s=>s.id===w.owner)?.venture!==scope))return note('this task is outside the selected workspace view.');return title('my work / assignment',E(w.title),'understand → do → evidence → review',button('back to my work','work','ghost'))+`<article class="card simple-task-detail"><span class="small">${E(l?.id||'internal work')} · ${E(workStatus(w))}</span><h2>1. understand the result</h2><p>${E(w.standard||'ask your supervisor to confirm the acceptance standard.')}</p><p class="small">owner: ${E(db.staff.find(s=>s.id===w.owner)?.name||w.owner||'to confirm')}<br>deadline: ${w.due?displayDate(w.due):'to confirm'}<br>reviewer: ${E(db.staff.find(s=>s.id===w.reviewer)?.name||w.reviewer||'venture delivery reviewer — confirm with your supervisor')}</p>${l?`<details><summary>client context & requirements</summary><p>${E(l.name)}</p><p>${E(l.next||'')}</p>${l.requirements.filter(r=>r.venture===w.venture||r.venture==='holding').map(r=>`<p>${E(r.title)} · ${E(r.status)}</p>`).join('')}</details>`:''}<h2>2. do the work</h2><p>follow the agreed standard. flag a blocker early so the team can help.</p><h2>3. add evidence</h2><form onsubmit="simpleTaskSubmit(event,'${kind}','${l?.id||'internal'}','${w.id}')"><label>result, evidence link or blocker</label><textarea name="evidence" required>${E(w.evidence||'')}</textarea><label>next action</label><select name="status"><option value="in progress">continue working</option><option value="blocked" ${w.status==='blocked'?'selected':''}>request help with a blocker</option><option value="under review">submit for review</option></select><h2>4. send the update</h2><p class="small">submitting sends this record to the review stage. final approval and delivery stay with the existing review controls.</p><button>save & submit update →</button></form>${l?`<details class="simple-extra"><summary>files, quality review & delivery controls</summary>${simpleDeliveryFor(l,w)}</details>`:''}</article>`}
function simpleDeliveryFor(l,w){let work=l.work;try{l.work=[w];return deliveryEditor(l)}finally{l.work=work}}
function simpleTaskSubmit(e,kind,lid,wid){e.preventDefault();let d=Object.fromEntries(new FormData(e.target)),w=kind==='client'?lead(lid).work.find(w=>w.id===wid):db.assignments.find(w=>w.id===wid);if(!d.evidence.trim())return;if(['delivered','approved'].includes(w.status)){toast('completed work requires a reviewer to reopen it');return}Object.assign(w,d,{updatedAt:now()});if(kind==='client')event(lead(lid),'task update: '+w.title+' / '+d.status);else save();toast('task update saved');go('work')}
function simpleHelp(){return title('help','you do not need to guess.','use the task context first, then ask the responsible person.')+`<section class="card"><h2>when you are stuck</h2><p>open the task, explain the blocker and choose “request help”. keep the client reference and next action attached to the work.</p><h2>when the work is ready</h2><p>add evidence and submit for review. the reviewer checks the result before final delivery.</p><h2>where are the other tools?</h2><p>open Manage for the catalogue, finance, people, resources, calendar and configuration. existing records remain in their original places.</p>${button('open my work →','work')}</section>`}
const simpleStaffRender=render;
render=function(){route=location.hash.slice(1).split('/');if(['task','staff-help'].includes(route[0])){root.innerHTML=demo()+workspace(route[0]==='task'?simpleTaskDetail():simpleHelp());attachLabels();drawChat()}else simpleStaffRender()};render();
